for f in sorted(glob.glob('/home/runner/work/Astra-Top-Games/Astra-Top-Games/games/*/readme.json')+glob.glob('/home/runner/work/Astra-Top-Games/Astra-Top-Games/games/*/*/readme.json')):
    try:
        d=json.load(open(f))
        print(f.split('games/')[1], '|', d.get('title'), '| rating', d.get('rating',{}).get('score'), '| shots', d.get('screenshot_based_score'))
    except Exception as e:
        print(f, e)
"

